import { CommonModule } from '@angular/common';
import { Component, Inject, Input, OnInit, Optional } from '@angular/core';
import { ControlContainer, FormGroupDirective } from '@angular/forms';
import {
	EspdAbstractInputDelegate,
	EspdAbstractInputDirective,
	EspdAbstractSizeableInputDirective,
	EspdControl,
	Sizes,
	espdAbstractInputComponentInjectionToken
} from 'espd-common/forms/api';
import { ControlLabelComponent } from 'espd-common/forms/control-label';
import { CountdownComponent } from 'espd-common/forms/countdown';
import { ErrorsComponent } from 'espd-common/forms/errors';
import { MessageConfig, MessageModule } from 'espd-common/i18n';

@Component({
	selector: 'espd-input-scaffold',
	templateUrl: './input-scaffold.component.html',
	imports: [
		CommonModule,
		ControlLabelComponent,
		CountdownComponent,
		ErrorsComponent,
		MessageModule
	],
	styleUrls: ['./input-scaffold.component.scss'],
	viewProviders: [{
		provide: ControlContainer,
		useExisting: FormGroupDirective
	}]
})
export class InputScaffoldComponent implements OnInit, EspdAbstractInputDelegate {

	@Input() public control?: EspdControl;
	@Input() public id!: number;
	@Input() public label?: MessageConfig | string;
	@Input() public labelSrOnly: boolean = false;
	@Input() public directions?: MessageConfig | string;
	@Input() public errorMessages!: { [key: string]: string | [string, any] };
	@Input() public maxLength?: number;
	@Input() public required: boolean = false;
	@Input() public width: number = Sizes.lg;
	@Input() public hideErrorMessages: boolean = false;
	@Input() public fieldSet: boolean = false;

	constructor(@Inject(espdAbstractInputComponentInjectionToken) @Optional() private espdAbstractInputDirective?: EspdAbstractInputDirective) { }

	public ngOnInit(): void {
		this.updateValues();
		this.registerDelegate();
	}

	public onInputConfigurationChange(): void {
		this.updateValues();
	}

	private registerDelegate() {
		this.espdAbstractInputDirective?.registerDelegate(this);
	}

	private updateValues() {
		if (this.espdAbstractInputDirective) {
			this.control = this.espdAbstractInputDirective.control ? this.espdAbstractInputDirective.control : this.control;
			this.id = this.espdAbstractInputDirective.id;
			this.label = this.espdAbstractInputDirective.label;
			this.labelSrOnly = this.espdAbstractInputDirective.labelSrOnly;
			this.directions = this.espdAbstractInputDirective.directions;
			this.errorMessages = this.espdAbstractInputDirective.errorMessages;
			this.required = this.espdAbstractInputDirective.required;
			this.hideErrorMessages = this.espdAbstractInputDirective.hideErrorMessages;

			if (this.espdAbstractInputDirective instanceof EspdAbstractSizeableInputDirective) {
				this.width = this.espdAbstractInputDirective.width;
			}
		}
	}
}